.last_child => (if (is_function) ":nth-last-child(" else ":last-child"),
.of_type => (if (is_function) ":nth-of-type(" else ":first-of-type"),
.last_of_type => (if (is_function) ":nth-last-of-type(" else ":last-of-type"),
