    pub fn toCss(this: *const @This(), dest: *css.Printer) css.PrintErr!void {
        return switch (this.*) {
            .all => try dest.writeStr("*"),
            .name => |name| try css.CustomIdentFns.toCss(&name, dest),
            .class => |name| {
                try dest.writeChar('.');
                try css.CustomIdentFns.toCss(&name, dest);
