                .result => |v| v,
                .err => |e| return .{ .err = e },
            } } };
        }

        return .{ .result = .{ .name = switch (css.css_values.ident.CustomIdent.parse(input)) {
            .result => |v| v,
            .err => |e| return .{ .err = e },
        } } };
    }

