                if (any_whitespace) {
                    combinator = .descendant;
                    break;
                } else {
                    break :outer_loop;
                }
            }
            if ((!state.allowsCombinators())) {
                return .{ .err = input.newCustomError(SelectorParseErrorKind.intoDefaultParserError(.invalid_state)) };
            }
            _ = builder.pushCombinator(combinator);
        }
        if ((!state.after_nesting)) {
            switch (nesting_requirement) {
.implicit => {
_ = builder.addNestingPrefix();
},
.contained, .prefixed => {
return .{ .err = input.newCustomError(SelectorParseErrorKind.intoDefaultParserError(.missing_nesting_selector)) };
},
else => {

},
}
        }
        const has_pseudo_element = (state.after_pseudo_element or state.after_unknown_pseudo_element);
        const slotted = state.after_slotted;
        const part = state.after_part;
        const result = builder.build(has_pseudo_element, slotted, part);
        return .{ .result = Selector{ .specificity_and_flags = result.specificity_and_flags, .components = result.components } };
}

pub fn parse_compound_selector(comptime Impl: type, parser: *SelectorParser, state: *SelectorParsingState, input: *css.Parser, builder: *SelectorBuilder(Impl)) Result(bool) {
        _ = input.skipWhitespace();
        var empty: bool = true;
        _ = &empty;
        if ((parser.isNestingAllowed() and (if (input.tryParse(css.Parser.expectDelim, .{ 38 }).isOk()) true else false))) {
            state.after_nesting = true;
            _ = builder.pushSimpleSelector(.nesting);
            empty = false;
        }
        if ((parse_type_selector(Impl, parser, input, state.*, builder).asValue() != null)) {
            empty = false;
        }
        parse_loop: while (true) {
            var result: SimpleSelectorParseResult(Impl) = undefined;
            _ = &result;
            {
                const ret = (switch (parse_one_simple_selector(Impl, parser, input, state)) {
.result => |r| r,
.err => |e| {
return .{ .err = e };
},
});
                if (ret) |res| {
                    _ = &res;
                    result = res;
                } else {
                    break :parse_loop;
                }
            }
            if (empty) {
                if (parser.defaultNamespace()) |url| {
                    _ = &url;
                    const ignore_default_ns = (state.skip_default_namespace or ((result == .simple_selector) and (result.simple_selector == .host)));
                    if ((!ignore_default_ns)) {
                        _ = builder.pushSimpleSelector(.{ .default_namespace = url });
                    }
                }
            }
            empty = false;
            switch (result) {
.simple_selector => {
_ = builder.pushSimpleSelector(result.simple_selector);
},
.part_pseudo => {
const selector = result.part_pseudo;
            state.after_part = true;
            _ = builder.pushCombinator(.part);
            _ = builder.pushSimpleSelector(.{ .part = selector });
},
.slotted_pseudo => |selector| {
state.after_slotted = true;
            _ = builder.pushCombinator(.slot_assignment);
            _ = builder.pushSimpleSelector(.{ .slotted = selector });
},
.pseudo_element => |p| {
if ((!p.isUnknown())) {
                state.after_pseudo_element = true;
                _ = builder.pushCombinator(.pseudo_element);
            } else {
                state.after_unknown_pseudo_element = true;
            }
            if ((!p.acceptsStatePseudoClasses())) {
                state.after_non_stateful_pseudo_element = true;
            }
            if (p.isWebkitScrollbar()) {
                state.after_webkit_scrollbar = true;
            }
            if (p.isViewTransition()) {
                state.after_view_transition = true;
            }
            _ = builder.pushSimpleSelector(.{ .pseudo_element = p });
},
}
        }
        return .{ .result = empty };
}

pub fn parse_relative_selector(comptime Impl: type, parser: *SelectorParser, input: *css.Parser, state: *SelectorParsingState, nesting_requirement_: NestingRequirement) Result(GenericSelector(Impl)) {
        var nesting_requirement = nesting_requirement_;
        _ = &nesting_requirement;
        const s = input.state();
        const combinator: ?Combinator = combinator: {
        const tok = (switch (input.next()) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
});
        switch (tok.*) {
.delim => |c| {
switch (c) {
'>' => {
break :combinator Combinator.child;
},
'+' => {
break :combinator Combinator.next_sibling;
},
'~' => {
break :combinator Combinator.later_sibling;
},
else => {

},
}
},
else => {

},
}
        _ = input.reset(s);
        break :combinator null;
};
        const scope: GenericComponent(Impl) = (if ((nesting_requirement == .implicit)) .nesting else .scope);
        if ((combinator != null)) {
            nesting_requirement = .none;
        }
        var selector = (switch (parse_selector(Impl, parser, input, state, nesting_requirement)) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
});
        _ = &selector;
        if (combinator) |wombo_combo| {
            _ = &wombo_combo;
            _ = ((selector.components.append(parser.allocator, .{ .combinator = wombo_combo })) catch unreachable);
            _ = ((selector.components.append(parser.allocator, scope)) catch unreachable);
        }
        return .{ .result = selector };
}

