pub fn pseudoClassIsEquivalent(a: *const PseudoClass, b: *const PseudoClass) bool {
        if (((a.* == .fullscreen) and (b.* == .fullscreen))) {
            return true;
        }
        if (((a.* == .any_link) and (b.* == .any_link))) {
            return true;
        }
        if (((a.* == .read_only) and (b.* == .read_only))) {
            return true;
        }
        if (((a.* == .read_write) and (b.* == .read_write))) {
            return true;
        }
        if (((a.* == .placeholder_shown) and (b.* == .placeholder_shown))) {
            return true;
        }
        if (((a.* == .autofill) and (b.* == .autofill))) {
            return true;
        }
        return a.eql(b);
}

pub fn selectorListDebugFormat(this_val: anytype, writer: *std.Io.Writer) std.Io.Writer.Error!void {
        if (comptime (!bun.Environment.isDebug)) {
            return;
        }
        _ = try writer.print("SelectorList[\n", .{});
        const last = (this_val.this.v.len() -| 1);
        const slice = this_val.this.v.slice();
        var i: usize = 0;
        _ = &i;
        while ((i < slice.len)) {
            const sel = (&slice[@as(usize, @intCast(i))]);
            if ((i != last)) {
                _ = try writer.print(" {f}\n", .{ sel.debug() });
            } else {
                _ = try writer.print(" {f},\n", .{ sel.debug() });
            }
            i = (i + 1);
        }
        return writer.print("]\n", .{});
}

