pub fn parsingStateAfterAnyPseudo(state: SelectorParsingState) bool {
        return ((state.after_part or state.after_slotted) or state.after_pseudo_element);
}

pub fn parsingStateAllowsPseudos(this_val: SelectorParsingState) bool {
        return ((!this_val.after_pseudo_element) and (!this_val.disallow_pseudos));
}

pub fn parsingStateAllowsPart(this_val: SelectorParsingState) bool {
        return ((!this_val.disallow_pseudos) and (!this_val.afterAnyPseudo()));
}

pub fn parsingStateAllowsSlotted(this_val: SelectorParsingState) bool {
        return this_val.allowsPart();
}

pub fn parsingStateAllowsTreeStructuralPseudoClasses(this_val: SelectorParsingState) bool {
        return (!this_val.afterAnyPseudo());
}

pub fn parsingStateAllowsNonFunctionalPseudoClasses(this_val: SelectorParsingState) bool {
        return ((!this_val.after_slotted) and (!this_val.after_non_stateful_pseudo_element));
}

pub fn parsingStateAllowsCombinators(this_val: SelectorParsingState) bool {
        return (!this_val.disallow_combinators);
}

pub fn parsingStateAllowsCustomFunctionalPseudoClasses(this_val: SelectorParsingState) bool {
        return (!this_val.afterAnyPseudo());
}

