        if (((a.* == .placeholder) and (b.* == .placeholder))) {
            return true;
        }
        if (((a.* == .backdrop) and (b.* == .backdrop))) {
            return true;
        }
        if (((a.* == .file_selector_button) and (b.* == .file_selector_button))) {
