},
.is => {
if (parser.parseIsAndWhere()) {
                return parse_is_or_where(Impl, parser, input, state, GenericComponent(Impl).convertHelper_is, .{});
            }
},
.where => {
if (parser.parseIsAndWhere()) {
                return parse_is_or_where(Impl, parser, input, state, GenericComponent(Impl).convertHelper_where, .{});
            }
},
.has => {
return parse_has(Impl, parser, input, state);
},
.host => {
if ((!state.allowsTreeStructuralPseudoClasses())) {
                return .{ .err = input.newCustomError(SelectorParseErrorKind.intoDefaultParserError(.invalid_state)) };
            } else {
                return .{ .result = .{ .host = (switch (parse_inner_compound_selector(Impl, parser, input, state)) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
}) } };
            }
},
.not => {
return parse_negation(Impl, parser, input, state);
},
}
        }
        if (parser.parseAnyPrefix(name)) |prefix| {
            _ = &prefix;
            return parse_is_or_where(Impl, parser, input, state, GenericComponent(Impl).convertHelper_any, .{ prefix });
        }
        if ((!state.allowsCustomFunctionalPseudoClasses())) {
            return .{ .err = input.newCustomError(SelectorParseErrorKind.intoDefaultParserError(.invalid_state)) };
        }
        const result = (switch (parser.parseNonTsFunctionalPseudoClass(name, input)) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
});
        return .{ .result = .{ .non_ts_pseudo_class = result } };
}

pub fn parse_simple_pseudo_class(comptime Impl: type, parser: *SelectorParser, location: css.SourceLocation, name: []const u8, state: SelectorParsingState) Result(GenericComponent(Impl)) {
        if ((!state.allowsNonFunctionalPseudoClasses())) {
            return .{ .err = location.newCustomError(SelectorParseErrorKind.intoDefaultParserError(.invalid_state)) };
        }
        if (state.allowsTreeStructuralPseudoClasses()) {
            if (TreeStructuralPseudoClassMap.getAnyCase(name)) |pseudo_class| {
                _ = &pseudo_class;
                switch (pseudo_class) {
.@"first-child" => {
return .{ .result = .{ .nth = NthSelectorData.first(false) } };
},
.@"last-child" => {
return .{ .result = .{ .nth = NthSelectorData.last(false) } };
},
.@"only-child" => {
return .{ .result = .{ .nth = NthSelectorData.only(false) } };
},
.root => {
return .{ .result = .root };
},
.empty => {
return .{ .result = .empty };
},
.scope => {
return .{ .result = .scope };
},
.host => {
if (parser.parseHost()) {
                    return .{ .result = .{ .host = null } };
                }
},
.@"first-of-type" => {
return .{ .result = .{ .nth = NthSelectorData.first(true) } };
},
.@"last-of-type" => {
return .{ .result = .{ .nth = NthSelectorData.last(true) } };
},
.@"only-of-type" => {
return .{ .result = .{ .nth = NthSelectorData.only(true) } };
},
}
            }
        }
        if (state.after_view_transition) {
            if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(name, "only-child")) {
                return .{ .result = .{ .nth = NthSelectorData.only(false) } };
            }
        }
        const pseudo_class = (switch (parser.parseNonTsPseudoClass(location, name)) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
});
        if (state.after_webkit_scrollbar) {
            if ((!pseudo_class.isValidAfterWebkitScrollbar())) {
                return .{ .err = location.newCustomError(SelectorParseErrorKind.intoDefaultParserError(.invalid_pseudo_class_after_webkit_scrollbar)) };
            }
        } else {
            if (state.after_pseudo_element) {
                if ((!pseudo_class.isUserActionState())) {
                    return .{ .err = location.newCustomError(SelectorParseErrorKind.intoDefaultParserError(.invalid_pseudo_class_after_pseudo_element)) };
                }
            } else {
                if ((!pseudo_class.isValidBeforeWebkitScrollbar())) {
                    return .{ .err = location.newCustomError(SelectorParseErrorKind.intoDefaultParserError(.invalid_pseudo_class_before_webkit_scrollbar)) };
                }
            }
        }
        return .{ .result = .{ .non_ts_pseudo_class = pseudo_class } };
}

pub fn parse_nth_pseudo_class(comptime Impl: type, parser: *SelectorParser, input: *css.Parser, state: SelectorParsingState, ty: NthType) Result(GenericComponent(Impl)) {
        if ((!state.allowsTreeStructuralPseudoClasses())) {
            return .{ .err = input.newCustomError(SelectorParseErrorKind.intoDefaultParserError(.invalid_state)) };
        }
        var a: i32 = 0;
        _ = &a;
        var b: i32 = 0;
        _ = &b;
        switch (css.nth.parse_nth(input)) {
.err => |e| {
return .{ .err = e };
},
.result => |v| {
a = v[0];
        b = v[1];
},
}
        const nth_data = NthSelectorData{ .ty = ty, .is_function = true, .a = a, .b = b };
        if ((!ty.allowsOfSelector())) {
            return .{ .result = .{ .nth = nth_data } };
        }
        if (input.tryParse(css.Parser.expectIdentMatching, .{ "of" }).isErr()) {
            return .{ .result = .{ .nth = nth_data } };
        }
        var child_state = child_state: {
        var s = ((&state)).*;
        _ = &s;
        s.skip_default_namespace = true;
        s.disallow_pseudos = true;
        break :child_state s;
};
        _ = &child_state;
        const selectors = (switch (SelectorList.parseWithState(parser, input, child_state, .ignore_invalid_selector, .none)) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
});
        const NthOf = NthOfSelectorData(Impl);
        return .{ .result = .{ .nth_of = NthOf{ .data = nth_data, .selectors = selectors.v.toOwnedSlice(input.allocator()) } } };
}

pub fn parse_is_or_where(comptime Impl: type, parser: *SelectorParser, input: *css.Parser, state: *SelectorParsingState, comptime func: anytype, args_: anytype) Result(GenericComponent(Impl)) {
        _ = bun.debugAssert(parser.parseIsAndWhere());
        var child_state = brk: {
        var child_state = state.*;
        _ = &child_state;
        child_state.skip_default_namespace = true;
        child_state.disallow_pseudos = true;
        break :brk child_state;
};
        _ = &child_state;
        const inner = (switch (SelectorList.parseWithState(parser, input, child_state, parser.isAndWhereErrorRecovery(), NestingRequirement.none)) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
});
        if (child_state.after_nesting) {
            state.after_nesting = true;
        }
        const selector_slice = inner.v.toOwnedSlice(input.allocator());
        const result = result: {
        const args = brk: {
        var args: std.meta.ArgsTuple(@TypeOf(func)) = undefined;
        _ = &args;
        args[cp_cast_int(usize, 0)] = selector_slice;
        inline for (args_) |a| {
            args[cp_cast_int(usize, 1)] = a;
        }
        break :brk args;
};
        break :result @call(.auto, func, args);
};
        return .{ .result = result };
}

pub fn parse_has(comptime Impl: type, parser: *SelectorParser, input: *css.Parser, state: *SelectorParsingState) Result(GenericComponent(Impl)) {
        var child_state = state.*;
        _ = &child_state;
        const inner = (switch (SelectorList.parseRelativeWithState(parser, input, (&child_state), parser.isAndWhereErrorRecovery(), .none)) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
});
        if (child_state.after_nesting) {
            state.after_nesting = true;
        }
        return .{ .result = .{ .has = inner.v.toOwnedSlice(input.allocator()) } };
}

pub fn parse_negation(comptime Impl: type, parser: *SelectorParser, input: *css.Parser, state: *SelectorParsingState) Result(GenericComponent(Impl)) {
        var child_state = state.*;
        _ = &child_state;
        child_state.skip_default_namespace = true;
        child_state.disallow_pseudos = true;
        const list = (switch (SelectorList.parseWithState(parser, input, (&child_state), .discard_list, .none)) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
});
        if (child_state.after_nesting) {
            state.after_nesting = true;
        }
        return .{ .result = .{ .negation = list.v.toOwnedSlice(input.allocator()) } };
}

pub fn OptionalQName(comptime Impl: type) type {
        return union(enum) {
        some: struct { QNamePrefix(Impl), ?[]const u8 },
        none: css.Token,
    };
}

pub fn QNamePrefix(comptime Impl: type) type {
        return union(enum) {
        implicit_no_namespace, // `foo` in attr selectors
        implicit_any_namespace, // `foo` in type selectors, without a default ns
        implicit_default_namespace: Impl.SelectorImpl.NamespaceUrl, // `foo` in type selectors, with a default ns
        explicit_no_namespace, // `|foo`
        explicit_any_namespace, // `*|foo`
        explicit_namespace: struct { Impl.SelectorImpl.NamespacePrefix, Impl.SelectorImpl.NamespaceUrl }, // `prefix|foo`
    };
}

pub fn parse_qualified_name(comptime Impl: type, parser: *SelectorParser, input: *css.Parser, in_attr_selector: bool) Result(OptionalQName(Impl)) {
        const start = input.state();
        const tok = (switch (input.nextIncludingWhitespace()) {
.result => |v| v,
.err => |e| {
{
            _ = input.reset(start);
            return .{ .err = e };
        }
},
});
        switch (tok.*) {
.ident => |value| {
const after_ident = input.state();
        var n: bool = false;
        _ = &n;
        if (input.nextIncludingWhitespace().asValue()) |tok_t| {
            _ = &tok_t;
            n = ((tok_t.* == .delim) and (tok_t.delim == 124));
        }
        if (n) {
            const prefix: Impl.SelectorImpl.NamespacePrefix = .{ .v = value };
            const result: ?Impl.SelectorImpl.NamespaceUrl = parser.namespaceForPrefix(prefix);
            if ((result == null)) {
                return .{ .err = input.newCustomError(SelectorParseErrorKind.intoDefaultParserError(.{ .unsupported_pseudo_class_or_element = value })) };
            }
            const url: Impl.SelectorImpl.NamespaceUrl = result.?;
            return parse_qualified_name_eplicit_namespace_helper(Impl, input, .{ .explicit_namespace = .{ prefix, url } }, in_attr_selector);
        } else {
            _ = input.reset(after_ident);
            if (in_attr_selector) {
                return .{ .result = .{ .some = .{ .implicit_no_namespace, value } } };
            }
            return .{ .result = parse_qualified_name_default_namespace_helper(Impl, parser, value) };
        }
},
.delim => |c| {
switch (c) {
'*' => {
const after_star = input.state();
        const result = input.nextIncludingWhitespace();
        if ((result).?.asValue()) |t_val| {
            _ = &t_val;
            if (((t_val.* == .delim) and (t_val.delim == 124))) {
                return parse_qualified_name_eplicit_namespace_helper(Impl, input, .explicit_any_namespace, in_attr_selector);
            }
        }
        _ = input.reset(after_star);
        if (in_attr_selector) {
            switch (result) {
.result => |t| {
return .{ .err = after_star.sourceLocation().newCustomError(SelectorParseErrorKind{ .expected_bar_in_attr = t.* }) };
},
.err => |e| {
return .{ .err = e };
},
else => {
_ = unreachable;
},
}
        } else {
            return .{ .result = parse_qualified_name_default_namespace_helper(Impl, parser, null) };
        }
},
'|' => {
return parse_qualified_name_eplicit_namespace_helper(Impl, input, .explicit_no_namespace, in_attr_selector);
},
else => {

},
}
},
else => {

},
}
        _ = input.reset(start);
        return .{ .result = .{ .none = tok.* } };
}

pub fn parse_qualified_name_default_namespace_helper(comptime Impl: type, parser: *SelectorParser, local_name: ?[]const u8) OptionalQName(Impl) {
        var namespace: QNamePrefix(Impl) = .implicit_any_namespace;
        _ = &namespace;
        if (parser.defaultNamespace()) |def_url| {
            _ = &def_url;
            namespace = .{ .implicit_default_namespace = def_url };
        }
        return .{ .some = .{ namespace, local_name } };
}

pub fn parse_qualified_name_eplicit_namespace_helper(comptime Impl: type, input: *css.Parser, namespace: QNamePrefix(Impl), in_attr_selector: bool) Result(OptionalQName(Impl)) {
        const location = input.currentSourceLocation();
        const t = (switch (input.nextIncludingWhitespace()) {
.result => |v| v,
.err => |e| {
return .{ .err = e };
},
});
        switch (t.*) {
.ident => |local_name| {
return .{ .result = .{ .some = .{ namespace, local_name } } };
},
.delim => |c| {
if ((c == 42)) {
            return .{ .result = .{ .some = .{ namespace, null } } };
        }
},
else => {

},
}
        if (in_attr_selector) {
            const e = SelectorParseErrorKind{ .invalid_qual_name_in_attr = t.* };
            return .{ .err = location.newCustomError(e) };
        }
        return .{ .err = location.newCustomError(SelectorParseErrorKind{ .explicit_namespace_unexpected_token = t.* }) };
}

