pub fn attributeFlagsToCaseSensitivity(this_val: AttributeFlags, local_name: []const u8, have_namespace: bool) attrs.ParsedCaseSensitivity {
        return (switch (this_val) {
.case_sensitive => .explicit_case_sensitive,
.ascii_case_insensitive => .ascii_case_insensitive,
.case_sensitivity_depends_on_name => {
{
            const AsciiCaseInsensitiveHtmlAttributes = enum {
                dir,
                http_equiv,
                rel,
                enctype,
                @"align",
                accept,
                nohref,
                lang,
                bgcolor,
                direction,
                valign,
                checked,
                frame,
                link,
                accept_charset,
                hreflang,
                text,
                valuetype,
                language,
                nowrap,
                vlink,
                disabled,
                noshade,
                codetype,
                @"defer",
                noresize,
                target,
                scrolling,
                rules,
                scope,
                rev,
                media,
                method,
                charset,
                alink,
                selected,
                multiple,
                color,
                shape,
                @"type",
                clear,
                compact,
                face,
                declare,
                axis,
                readonly,
            };
            const Map = (comptime bun.ComptimeEnumMap(AsciiCaseInsensitiveHtmlAttributes));
            if (((!have_namespace) and Map.has(local_name))) {
                return .ascii_case_insensitive_if_in_html_element_in_html_document;
            }
            return .case_sensitive;
        }
},
});
}

pub fn parse_attribute_flags(input: *css.Parser) Result(AttributeFlags) {
        const location = input.currentSourceLocation();
        const token = (switch (input.next()) {
.result => |v| v,
.err => {
return .{ .result = AttributeFlags.case_sensitivity_depends_on_name };
},
});
        if ((token.* != .ident)) {
            return .{ .err = location.newBasicUnexpectedTokenError(token.*) };
        }
        const ident = token.ident;
        if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(ident, "i")) {
            return .{ .result = AttributeFlags.ascii_case_insensitive };
        } else {
            if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(ident, "s")) {
                return .{ .result = AttributeFlags.case_sensitive };
            } else {
                return .{ .err = location.newBasicUnexpectedTokenError(token.*) };
            }
        }
}
